#!/usr/bin/env node
/**
 * tred-tuteur-qui-cherche.mjs
 *
 * Les deux causes de « le tuteur n'est pas vraiment intelligent » :
 *
 *   1. Il n'avait pas le droit de reflechir. Aucun raisonnement etendu :
 *      une derivation de moment flechissant se faisait en un seul passage,
 *      sans brouillon. Corrige par thinking adaptive.
 *
 *   2. Il ne voyait qu'un quart du cours, choisi par correspondance de mots
 *      exacts. Une question sur la « Maschengleichung » ne trouvait pas le
 *      chapitre « Kirchhoffsche Regeln » — et il repondait de memoire
 *      generale. Corrige par l'outil suche_in_unterlagen, qui cherche dans
 *      TOUT le corpus et qu'il peut relancer avec d'autres mots.
 *
 * Le test document-search.test.ts PROUVE l'ecart : BM25 sur la question rate
 * le passage, la recherche du tuteur le trouve.
 *
 * Contient aussi la bibliotheque de cours et les schemas circuitikz.
 *
 * Verifie : tsc 0, bun test 155/155, vite build,
 * bun install --frozen-lockfile 0, build:web 0.
 *
 *   node tred-tuteur-qui-cherche.mjs
 */
import { writeFileSync, mkdirSync, existsSync, rmSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { inflateSync } from "node:zlib";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = resolve(depart);
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const parent = dirname(d);
      if (parent === d) break;
      d = parent;
    }
  }
  return null;
}

const R = racine();
if (!R) {
  console.error("Depot introuvable. Lance-le depuis C:\\dev\\tred-rdm\\aerostudy-ai.");
  process.exit(1);
}
console.log("Depot :", R, "\n");

const PAYLOAD = "";

const LOT = JSON.parse(inflateSync(Buffer.from(PAYLOAD, "base64")).toString("utf8"));
let n = 0;
for (const [chemin, b64] of Object.entries(LOT.ecrire)) {
  const cible = join(R, chemin);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  n++;
}
for (const chemin of LOT.supprimer) {
  const cible = join(R, chemin);
  if (existsSync(cible)) rmSync(cible);
}

console.log(`${n} fichiers poses.\n`);
console.log("1) La base, si ce n'est pas deja fait :");
console.log("     node migre-cours.mjs");
console.log("\n2) L'envoi (premiere construction : +4 a 6 min, TeX Live) :");
console.log("     git add -A");
console.log("     git commit -m \"le tuteur reflechit et cherche dans tout le cours\"");
console.log("     git push");
console.log("\n3) Dans le journal Railway, attends la ligne :");
console.log("     chaine LaTeX complete");
console.log("\n4) Puis, dans le chat, pose une question dont le mot n'est PAS");
console.log("   celui du polycopie. C'est le seul vrai essai.");
